@torch.no_grad()
def _rollout_action_chunk_skip_terminal(self, chunk_index, action_shape, action_mask, prompt_emb, ego_cond, num_steps):
    actions = torch.randn(action_shape, device=self.device, dtype=self.dtype)
    actions = torch.where(action_mask, actions, torch.zeros_like(actions))
    timesteps = self._prepare_timesteps(self.action_scheduler, num_steps)
    for (step_id, t) in enumerate(timesteps):
        last_step = step_id == len(timesteps) - 1
        if last_step:
            break
        actions = torch.where(action_mask, actions, torch.zeros_like(actions))
        timestep_tensor = torch.full((1, actions.shape[2]), float(t.item()), device=self.device, dtype=torch.float32)
        input_dict = self._make_action_input(actions, timestep_tensor, prompt_emb, ego_cond, chunk_index=chunk_index)
        action_pred_seq = self.transformer(input_dict, update_cache=1 if last_step else 0, cache_name=self.cache_name, action_mode=True)
        if last_step:
            continue
        action_pred = rearrange(action_pred_seq, 'b (f n) c -> b c f n 1', f=actions.shape[2])
        actions = self.action_scheduler.step(action_pred, t, actions)
    return torch.where(action_mask, actions, torch.zeros_like(actions))
